//! celestia-app v10's interface registry, as far as tx decoding observes it.
//!
//! [`TYPE_URLS`] is generated by `conformance/txdecode` from the registry Go
//! builds in `encoding.MakeConfig(app.ModuleEncodingRegisters...)`: the
//! SDK `std.RegisterInterfaces` plus every module's `RegisterInterfaces`. It
//! lists the registry's `typeURLMap` (resolvable inside any `Any`) and, per
//! type URL, the interfaces whose `interfaceImpls` contain it (what
//! `UnpackAny` accepts for a given interface). The conformance test checks it
//! against `conformance/fixtures/txdecode/registry.json`.

use celestia_proto::wire_table::MessageInfo;

/// Interface bits.
pub(crate) mod iface {
    /// `sdk.Msg` (`cosmos.base.v1beta1.Msg`).
    pub(crate) const MSG: u32 = 1 << 0;
    /// `cryptotypes.PubKey`.
    pub(crate) const PUB_KEY: u32 = 1 << 1;
    /// `authz.Authorization`.
    pub(crate) const AUTHORIZATION: u32 = 1 << 2;
    /// `feegrant.FeeAllowanceI`.
    pub(crate) const FEE_ALLOWANCE: u32 = 1 << 3;
    /// gov `v1beta1.Content`.
    pub(crate) const CONTENT: u32 = 1 << 4;
    /// evidence `exported.Evidence`.
    pub(crate) const EVIDENCE: u32 = 1 << 5;
    /// ibc `exported.ClientState`.
    pub(crate) const CLIENT_STATE: u32 = 1 << 6;
    /// ibc `exported.ConsensusState`.
    pub(crate) const CONSENSUS_STATE: u32 = 1 << 7;
    /// ibc `exported.ClientMessage`.
    pub(crate) const CLIENT_MESSAGE: u32 = 1 << 8;
    /// `tx.TxExtensionOptionI` (registered without implementations).
    pub(crate) const TX_EXTENSION_OPTION: u32 = 1 << 9;
}

include!("registry_table.rs");

fn lookup(type_url: &[u8]) -> Option<&'static (&'static str, &'static str, u32)> {
    TYPE_URLS
        .binary_search_by(|(u, _, _)| u.as_bytes().cmp(type_url))
        .ok()
        .map(|i| &TYPE_URLS[i])
}

/// `interfaceRegistry.Resolve`: the message type registered under a type URL.
pub(crate) fn resolve(type_url: &[u8]) -> Option<&'static MessageInfo> {
    lookup(type_url).and_then(|(_, name, _)| celestia_proto::wire_table::message(name))
}

/// The implementation of `iface` registered under `type_url`, if any.
pub(crate) fn resolve_impl(type_url: &[u8], iface: u32) -> Option<&'static MessageInfo> {
    lookup(type_url)
        .filter(|(_, _, bits)| bits & iface != 0)
        .and_then(|(_, name, _)| celestia_proto::wire_table::message(name))
}

/// Whether `iface` has any registered implementation (`interfaceImpls`
/// entry). `TxExtensionOptionI` has none.
pub(crate) fn has_impls(iface: u32) -> bool {
    TYPE_URLS.iter().any(|(_, _, bits)| bits & iface != 0)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sorted_and_resolvable() {
        assert!(TYPE_URLS.windows(2).all(|w| w[0].0 < w[1].0));
        for (url, name, _) in TYPE_URLS {
            assert!(
                celestia_proto::wire_table::message(name).is_some(),
                "{url} -> {name} not in schema"
            );
        }
        assert!(resolve_impl(b"/cosmos.bank.v1beta1.MsgSend", iface::MSG).is_some());
        assert!(resolve_impl(b"/cosmos.bank.v1beta1.MsgSend", iface::PUB_KEY).is_none());
        assert!(!has_impls(iface::TX_EXTENSION_OPTION));
    }
}
